import crypto from 'crypto';
import express from 'express';
import jwt from 'jsonwebtoken';
import mongoose from 'mongoose';
import passport from 'passport';
import rateLimit from 'express-rate-limit';
import User from '../models/User.js';
import authMiddleware from '../middleware/auth.js';
import { usuarioPublico } from '../utils/usuarioPublico.js';
import { enviarEmailReset } from '../utils/emailService.js';

const router = express.Router();

// Rate limiter para rotas de autenticação (10 tentativas por 15 min)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { sucesso: false, mensagem: 'Muitas tentativas. Tente novamente em 15 minutos.' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Rate limiter para forgot-password (3 tentativas por hora)
const forgotLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 3,
  message: { sucesso: false, mensagem: 'Muitas solicitações de recuperação. Tente novamente em 1 hora.' },
  standardHeaders: true,
  legacyHeaders: false,
});

// Lidos em runtime para garantir que dotenv já carregou
const getJwtSecret = () => process.env.JWT_SECRET;
const getFrontendUrl = () => process.env.FRONTEND_URL || 'http://localhost:5173';

const signToken = (userId) =>
  jwt.sign({ id: userId }, getJwtSecret(), { expiresIn: '7d' });

